final class MarketingAssetMutationAudit { public function __construct(private readonly ActivityLogService $log){} public function record(Authenticatable $user,string $action,int $id,int $client,array $data=[],?string $tool=null):void{$safe=array_diff_key($data,array_flip(['confirmation_token','password','credential','secret','private_key','location','path','storage_path','binary','file_base64']));$this->log->record(['action'=>strtoupper($action),'module'=>'marketing_asset_metadata','target_id'=>$id,'target_type'=>'marketing_asset_metadata','description'=>'Marketing asset metadata mutation '.$action,'context'=>['client_id'=>$client,'tool'=>$tool??'marketing_'.strtolower($action).'_asset_metadata','record_id'=>$id,'operation'=>strtolower($action),'result'=>'success','status'=>'completed','occurred_at'=>now()->toIso8601String()],'new_data'=>$safe],$user);} }
